import clsx from "clsx";

/**
 * @summary 항목 트리 렌더러 입력
 */
interface EntryTreeProps {
  /**
   * @field 트리에 표시할 항목 목록
   */
  entries: Array<{id: string; label: string}>;
  /**
   * @field 현재 선택된 항목 ID
   */
  selectedId?: string;
}

export const EntryTree = (props: EntryTreeProps) => {
  const {entries, selectedId} = props;

  return (
    <ul className={clsx("ui_entryTree", selectedId && "ui_entryTree--selected")}>
      {entries.map((entry) => (
        <li key={entry.id}>{entry.label}</li>
      ))}
    </ul>
  );
};
